// ipamUsage displays the usage of the ipam command and its subcommands.
func ipamUsage() {
	fmt.Fprintln(os.Stderr, `Reserve, release, and list address-space and UDP-port allocations for one tailnet's registry.`)
	fmt.Fprintf(os.Stderr, "Usage:\n    %s [globalflags] ipam COMMAND [flags]\n\n", os.Args[0])
	fmt.Fprintln(os.Stderr, "COMMAND:")
	fmt.Fprintln(os.Stderr, `    plan: Compare declared allocations with live control-plane state without modifying either.`)
	fmt.Fprintln(os.Stderr, `    check-policy: Compare static ipset definitions with subnet reservations without modifying either.`)
	fmt.Fprintln(os.Stderr, `    list-history: List the audit events of one tailnet's registry, newest first.`)
	fmt.Fprintln(os.Stderr, `    list-site-ids: ListSiteIds implements list_site_ids.`)
	fmt.Fprintln(os.Stderr, `    reserve-site-id: ReserveSiteID implements reserve_site_id.`)
	fmt.Fprintln(os.Stderr, `    release-site-id: ReleaseSiteID implements release_site_id.`)
	fmt.Fprintln(os.Stderr, `    list-subnet-pools: ListSubnetPools implements list_subnet_pools.`)
	fmt.Fprintln(os.Stderr, `    reserve-subnet-pool: ReserveSubnetPool implements reserve_subnet_pool.`)
	fmt.Fprintln(os.Stderr, `    allocate-subnet-pool: Reserve the first free child CIDR of a pool for a site in one locked read-decide-write transaction. Registry reservations for every site and the caller-supplied live routes both count as taken.`)
	fmt.Fprintln(os.Stderr, `    release-subnet-pool: ReleaseSubnetPool implements release_subnet_pool.`)
	fmt.Fprintln(os.Stderr, `    list-service-addresses: ListServiceAddresses implements list_service_addresses.`)
	fmt.Fprintln(os.Stderr, `    reserve-service-address: ReserveServiceAddress implements reserve_service_address.`)
	fmt.Fprintln(os.Stderr, `    release-service-address: ReleaseServiceAddress implements release_service_address.`)
	fmt.Fprintln(os.Stderr, `    list-udp-ports: ListUDPPorts implements list_udp_ports.`)
	fmt.Fprintln(os.Stderr, `    reserve-udp-port: ReserveUDPPort implements reserve_udp_port.`)
	fmt.Fprintln(os.Stderr, `    release-udp-port: ReleaseUDPPort implements release_udp_port.`)
	fmt.Fprintln(os.Stderr)
	fmt.Fprintln(os.Stderr, "Additional help:")
	fmt.Fprintf(os.Stderr, "    %s ipam COMMAND --help\n", os.Args[0])
}
